<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireRole(['supervisor','system_admin']);$pdo=$db->getConnection();$threads=[];try{$threads=$pdo->query("SELECT sm.user_id,u.full_name,COUNT(*) message_count,MAX(sm.created_at) last_message FROM support_messages sm LEFT JOIN users u ON sm.user_id=u.id GROUP BY sm.user_id,u.full_name ORDER BY last_message DESC")->fetchAll();}catch(Throwable $e){}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Support Supervisor</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-5"><h2>Support Supervisor</h2><table class="table"><thead><tr><th>User</th><th>Messages</th><th>Last activity</th></tr></thead><tbody><?php foreach($threads as $t):?><tr><td><?=htmlspecialchars($t['full_name']??('User '.$t['user_id']))?></td><td><?=intval($t['message_count'])?></td><td><?=htmlspecialchars($t['last_message'])?></td></tr><?php endforeach;?></tbody></table></div></body></html>